#!/usr/bin/env bash
#
# The CONTENT KEY of a deployable (ADR-0067): the sha256 of the git objects of every path it is built FROM.
#
# The paths are the deployable's rows in `docs/generated/infrastructure/imageClosures.tsv`, generated by
# `scripts/infrastructureManifest.mjs` under its staleness gate. Each path is resolved to its git object id AT THE
# REVISION (a tree for a directory, a blob for a file), the `<path> <id>` lines are sorted, prefixed with the key
# schema version, and hashed. So:
#
#  - the same inputs give the same key in any commit (a merge commit included), and the key never holds a commit sha;
#  - an edit inside the closure gives a new key, and an edit outside it (a CDK app, a guard, a test) does not.
#
# `imageTag.sh content <key>` turns it into the image tag, `ck-<key>`.
#
#   bash .github/scripts/deployKey.sh key <deployable> [<revision>] [--require-clean]
#
# The revision defaults to HEAD. In CI that is `github.sha`, the tree the workflow checked out and builds.
#
# ⛔ A closure path the revision does not hold is a STALE closure, and is refused: skipping it would hash fewer
#    inputs than the build reads, and two different builds would share one key.
# ⛔ `--require-clean` refuses uncommitted changes to a closure path: a key read from the revision while the tree
#    holds something else names an image that nothing can rebuild. Every CI call passes it.
#
# Exit 0 with the key on stdout. Exit 1 when the closure is stale or names no such deployable, 3 when the closure is
# dirty under `--require-clean`, and 2 on usage — each with NOTHING on stdout, so a `$(...)` caller never reads half a
# key. Pure apart from reading git.
#
# @sideEffect Reads the git repository the working directory is in.
set -euo pipefail

# The key schema version. Bump it when the way a key is computed changes, so no old key can collide with a new one.
KEY_SCHEMA='deployKey v1'
CLOSURES='docs/generated/infrastructure/imageClosures.tsv'

usage() {
    echo 'usage: deployKey.sh key <deployable> [<revision>] [--require-clean]' >&2
    exit 2
}

[ "${1-}" = key ] || usage
DEPLOYABLE="${2-}"
[ -n "$DEPLOYABLE" ] || usage
REVISION=HEAD
REQUIRE_CLEAN=false
for argument in "${@:3}"; do
    case "$argument" in
        --require-clean) REQUIRE_CLEAN=true ;;
        -*) usage ;;
        *) REVISION="$argument" ;;
    esac
done

if ! closure_file="$(git show "${REVISION}:${CLOSURES}" 2>/dev/null)"; then
    echo "::error::deploy-key: ${REVISION} holds no ${CLOSURES}" >&2
    exit 1
fi

paths=()
while IFS=$'\t' read -r deployable path; do
    case "$deployable" in '' | '#'*) continue ;; esac
    if [ "$deployable" = "$DEPLOYABLE" ]; then
        paths+=("$path")
    fi
done <<<"$closure_file"

if [ "${#paths[@]}" -eq 0 ]; then
    echo "::error::deploy-key: ${CLOSURES} names no deployable '${DEPLOYABLE}'" >&2
    exit 1
fi

if [ "$REQUIRE_CLEAN" = true ]; then
    dirty="$(git status --porcelain -- "${paths[@]}")"
    if [ -n "$dirty" ]; then
        echo "::error::deploy-key: ${DEPLOYABLE}'s closure has uncommitted changes, so its key would name an image nothing can rebuild:" >&2
        printf '%s\n' "$dirty" >&2
        exit 3
    fi
fi

lines=()
missing=()
for path in "${paths[@]}"; do
    if id="$(git rev-parse --verify --quiet "${REVISION}:${path}")"; then
        lines+=("${path} ${id}")
    else
        missing+=("$path")
    fi
done

if [ "${#missing[@]}" -gt 0 ]; then
    echo "::error::deploy-key: ${REVISION} does not hold ${DEPLOYABLE}'s closure path(s) ${missing[*]}; the closure is stale. Run \`npm run infra:manifest\`." >&2
    exit 1
fi

{
    echo "$KEY_SCHEMA"
    echo "deployable ${DEPLOYABLE}"
    printf '%s\n' "${lines[@]}" | LC_ALL=C sort
} | sha256sum | cut -d' ' -f1
